from pathlib import Path
import sys,subprocess,wave,json,hashlib
R=Path.cwd();D=R/'build/classic-audio';A=D/'alternate-sources';sys.path.insert(0,str(R/'build/audio-tools'));import imageio_ffmpeg
out=D/'classic-bourvil-corniaud.wav';subprocess.run([imageio_ffmpeg.get_ffmpeg_exe(),'-y','-hide_banner','-loglevel','error','-i',str(A/'bourvil-full.wav'),'-af','atrim=start=61:end=64,asetpts=PTS-STARTPTS,loudnorm=I=-18:TP=-2:LRA=9,adelay=220:all=1','-ar','44100','-ac','1',str(out)],check=True,capture_output=True)
rows=json.loads((R/'audio-bank/classic-reactions-candidates.json').read_text(encoding='utf8'))
r=next(r for r in rows if r['id']=='classic-bourvil-corniaud');r.update(file=out.name,audioStatus='local_audition',status='approved_audio_retrieved',downloadSourceUrl='https://www.youtube.com/watch?v=FNVQg0DBLwo',trimStartSeconds=61,trimEndSeconds=64,reviewNote='Retrieved from an alternate public scene excerpt. Local transcription locates the matching line at 61–64 seconds; original selection approved by user.',sha256=hashlib.sha256(out.read_bytes()).hexdigest())
with wave.open(str(out)) as w:r['durationSeconds']=round(w.getnframes()/w.getframerate(),3);assert w.getnchannels()==1 and w.getframerate()==44100
(R/'audio-bank/classic-reactions-candidates.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
p=D/'index.html';s=p.read_text(encoding='utf8');needle='<p><a href="'+r['sourceUrl']+'">';s=s.replace(needle,'<audio controls preload="none" src="./classic-bourvil-corniaud.wav"></audio>'+needle);s=s.replace('Deux fichiers locaux à écouter','Trois fichiers locaux à écouter').replace('19 autres répliques attendent leur audio.','La réplique de Bourvil est désormais récupérée depuis une autre source ; les autres restent en recherche.');p.write_text(s,encoding='utf8')
p=R/'audio-bank/CLASSIC-REACTIONS.md';s=p.read_text(encoding='utf8');s+='\n## Source alternative retrouvée\n\nLa réplique du Corniaud de Bourvil a été récupérée à partir de [cet extrait vidéo public](https://www.youtube.com/watch?v=FNVQg0DBLwo). La phrase est repérée entre 61 et 64 secondes dans la transcription locale. Une découpe normalisée est disponible dans `build/classic-audio/classic-bourvil-corniaud.wav`. Elle n’est pas encore installée dans la banque du jeu.\n';p.write_text(s,encoding='utf8')
print('Retrieved and prepared Bourvil line:',r['durationSeconds'],'seconds. Existing game bank unchanged.')
